// Class 11 English Core: Notice, Poster & Advertisement Writing (c11-eng-w2)
// Section B: Short Writing Skills (4 Marks Guaranteed Strategy)
// Fully aligned with CBSE & JKBOSE curriculum standards.

export const c11EngW2HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & EXAM BLUEPRINT CARD -->\n  <div style=\"background: rgba(0, 198, 255, 0.06); border: 1.5px solid #00C6FF; border-radius: 12px; padding: 18px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h2 class=\"text-center\" style=\"color: #00C6FF; font-weight: bold; margin: 0 0 6px 0; font-size: 20px;\">📢 Notice, Poster &amp; Advertisement Writing &mdash; Master Blueprint</h2>\n    <p class=\"text-center\" style=\"color: #80D8FF; margin: 0 0 16px 0; font-size: 14.5px;\">Short Composition Hub &bull; Section B &bull; 4 Marks Complete Strategy</p>\n\n    <div style=\"display: flex; flex-direction: column; gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #00C6FF; border-radius: 6px;\">\n        <b style=\"color: #00C6FF; font-size: 16px; display: block; margin-bottom: 4px;\">1. Official Board Marking Scheme (4 Marks Total):</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">\n          &bull; <b>Format:</b> 1 Mark (Box enclosure, official heading/category, date, captivating title, issuing authority/designation or contact details).<br/>\n          &bull; <b>Content:</b> 2 Marks (All essential 5 Ws: What, Where, When, Who, Whom, entry fees, eligibility, and deadline).<br/>\n          &bull; <b>Expression:</b> 1 Mark (Grammatical accuracy, appropriate formal/telegraphic register, cohesion, strict adherence to 50 words).\n        </span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #00C6FF; border-radius: 6px;\">\n        <b style=\"color: #00C6FF; font-size: 16px; display: block; margin-bottom: 4px;\">2. Mandatory Structural Imperatives:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">\n          Every Notice, Poster, and Advertisement <b>MUST BE DRAWN INSIDE A NEAT RECTANGULAR BOX</b>. Forgetting to draw the bounding box attracts an immediate 0.5 to 1 mark deduction by board examiners.\n        </span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #00C6FF; border-radius: 6px;\">\n        <b style=\"color: #00C6FF; font-size: 16px; display: block; margin-bottom: 4px;\">3. Strict Word Limit (50 Words):</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">\n          Short compositions test the writer&rsquo;s ability to transmit maximum factual data in minimum words. Exceeding 50 words invites negative marking for expression. Use concise phrases and omit unnecessary pronouns.\n        </span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: NOTICE WRITING -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 30px;\">1. Notice Writing Masterclass</h2>\n  <p>A notice is an official written announcement designed to broadcast vital information to a targeted group of people (such as students, club members, residents, or the general public). It is displayed prominently on public notice boards and must convey its message instantaneously without ambiguity.</p>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(i) The Five Ws of Content:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Every full-scoring notice must systematically answer: <b>WHAT</b> is going to happen (event/purpose), <b>WHERE</b> it will take place (venue), <b>WHEN</b> it will take place (date and time), <b>WHO</b> can participate/attend (eligibility/target audience), and <b>WHOM</b> to contact for further details or registration.</p>\n    </div>\n\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(ii) Standard Format Layout &amp; Flow:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">\n        1. <b>Name of Issuing Organisation / Institution</b> (Top center, in bold capitals).<br/>\n        2. The word <b>NOTICE</b> (Centrally placed, bold capital letters).<br/>\n        3. <b>Date of Issue</b> (Left-aligned, alphanumeric format like <i>15th October 2026</i>; never write numerical slashes like <i>15/10/26</i>).<br/>\n        4. <b>Eye-catching Subject / Heading</b> (Center-aligned, concise, summarizing the event).<br/>\n        5. <b>Body of Notice</b> (Single concise paragraph stating the 5 Ws, contact deadline, and instructions).<br/>\n        6. <b>Sign-off Block</b> (Left-aligned: Signature, Full Name in brackets, and Official Designation).\n      </p>\n    </div>\n\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(iii) Stylistic &amp; Tone Requirements:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Write in the formal third-person perspective (<i>&ldquo;Students of Class XI are hereby informed...&rdquo;</i>). Strictly avoid first-person pronouns like <i>&ldquo;I&rdquo;</i>, <i>&ldquo;me&rdquo;</i>, or <i>&ldquo;we&rdquo;</i>. Use passive voice constructions to emphasize the event rather than the writer.</p>\n    </div>\n  </div>\n\n  <!-- NOTICE GOLDEN TEMPLATE CARD -->\n  <div style=\"background: #111B27; border: 2px dashed #00C6FF; border-radius: 10px; padding: 18px; margin: 24px 0; box-shadow: 0 4px 18px rgba(0,0,0,0.4);\">\n    <div style=\"text-align: center; color: #00C6FF; font-size: 13px; font-weight: bold; letter-spacing: 1.5px; margin-bottom: 8px;\">[MANDATORY RECTANGULAR BOX]</div>\n    <div style=\"text-align: center; font-weight: bold; font-size: 17px; color: #FFFFFF; letter-spacing: 1px;\">NAME OF THE ISSUING SCHOOL / INSTITUTION, CITY</div>\n    <div style=\"text-align: center; font-weight: 800; font-size: 19px; color: #00C6FF; letter-spacing: 3px; margin: 8px 0;\">NOTICE</div>\n    <div style=\"display: flex; justify-content: space-between; margin-bottom: 12px; font-size: 14.5px; color: #CBD5E1;\">\n      <span><b>Date:</b> 15th October 2026</span>\n      <span style=\"color: #64748B;\">[Left-Aligned Date]</span>\n    </div>\n    <div style=\"text-align: center; font-weight: bold; font-size: 16px; color: #FFD54F; margin-bottom: 14px; text-decoration: underline;\">\n      EYE-CATCHING AND PRECISE SUBJECT / TITLE\n    </div>\n    <p style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7; margin-bottom: 16px;\">\n      This is to inform all students/residents that [Event Name] will be organized by [Club/Authority] on [Day &amp; Date] at [Time] in the [Venue]. The event aims to [Purpose]. Interested candidates who wish to participate must submit their names along with [Registration Fee / Consent Slip] to the undersigned no later than [Last Date]. For any additional queries, contact the undersigned.\n    </p>\n    <div style=\"margin-top: 14px; color: #E2E8F0; font-size: 14.5px;\">\n      <div>Sd/-</div>\n      <div style=\"font-weight: bold; color: #FFFFFF;\">(RAHUL SHARMA)</div>\n      <div style=\"color: #80D8FF; font-size: 14px;\">Head Boy / Secretary, Cultural Club</div>\n    </div>\n  </div>\n\n  <!-- SECTION 2: POSTER DESIGNING -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 35px;\">2. Poster Designing Masterclass</h2>\n  <p>A poster is a large, visually stimulating printed notice designed to capture the attention of passers-by from a distance. It combines persuasive verbal slogans, visual motifs, and practical information to generate public awareness on social, environmental, or health crises, or to advertise cultural exhibitions and charity events.</p>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(i) Visual Architecture &amp; Typography:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">A poster must not read like an essay. It uses varied font weights, bold catchphrases, rhyming slogans, bulleted key points, and neat geometric framing. Proportionate spacing is vital &mdash; no clutter, no cramped corners.</p>\n    </div>\n\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(ii) Core Components of an Awareness Poster:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">\n        1. <b>Theme Slogan:</b> High-impact, memorable punchline at the top (e.g. <i>&ldquo;DON&rsquo;T BE MEAN &mdash; GO GREEN!&rdquo;</i>).<br/>\n        2. <b>Visual Graphic / Motif:</b> Simple illustrative line drawings or symbolic icons (e.g., dripping tap, leafy tree, smoking cigarette with a red cross).<br/>\n        3. <b>Core Message / Action Points:</b> 3 to 4 succinct action imperatives (Dos and Don&rsquo;ts, preventive measures, or consequences).<br/>\n        4. <b>Issued In Public Interest By:</b> The name of the sponsoring ministry, NGO, or school at the bottom.\n      </p>\n    </div>\n\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(iii) Core Components of an Event Poster:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Must clearly specify the occasion, purpose, chief guest, date, time, venue, entry requirements (e.g., passes/tickets), and organizer contact info.</p>\n    </div>\n  </div>\n\n  <!-- POSTER GOLDEN TEMPLATE CARD -->\n  <div style=\"background: #0B192C; border: 2px solid #00C6FF; border-radius: 10px; padding: 18px; margin: 24px 0; box-shadow: 0 4px 20px rgba(0, 198, 255, 0.15); text-align: center;\">\n    <div style=\"color: #00C6FF; font-size: 12px; font-weight: bold; letter-spacing: 2px;\">[POSTER BOX CONTAINER]</div>\n    <div style=\"font-size: 22px; font-weight: 900; color: #FFEB3B; letter-spacing: 1.5px; margin: 10px 0; text-transform: uppercase;\">\n      ★ SAVE WATER &bull; SAVE LIFE &bull; SAVE EARTH ★\n    </div>\n    <div style=\"font-size: 16px; color: #80D8FF; font-style: italic; margin-bottom: 14px;\">\n      &ldquo;A Single Drop of Water is Worth More Than a Sack of Gold to a Thirsty Soul!&rdquo;\n    </div>\n    <div style=\"display: flex; justify-content: space-around; background: rgba(0,0,0,0.3); padding: 12px; border-radius: 8px; margin: 14px 0; text-align: left;\">\n      <div style=\"width: 48%;\">\n        <b style=\"color: #00E676; display: block; margin-bottom: 6px;\">✔ WHAT YOU MUST DO:</b>\n        <span style=\"font-size: 14px; color: #FFFFFF; line-height: 1.6;\">\n          &bull; Turn off running taps while brushing.<br/>\n          &bull; Adopt rainwater harvesting in homes.<br/>\n          &bull; Reuse greywater for gardening.<br/>\n          &bull; Repair leaking pipes immediately.\n        </span>\n      </div>\n      <div style=\"width: 48%;\">\n        <b style=\"color: #FF5252; display: block; margin-bottom: 6px;\">✖ WHAT YOU MUST AVOID:</b>\n        <span style=\"font-size: 14px; color: #FFFFFF; line-height: 1.6;\">\n          &bull; Never use hosepipes to wash cars.<br/>\n          &bull; Avoid long shower sessions.<br/>\n          &bull; Stop dumping waste in fresh streams.<br/>\n          &bull; Don&rsquo;t ignore community water leaks.\n        </span>\n      </div>\n    </div>\n    <div style=\"font-weight: bold; color: #FFD54F; font-size: 15px; margin: 10px 0;\">\n      REMEMBER: IF YOU CUT OFF WATER TODAY, NATURE WILL CUT OFF LIFE TOMORROW!\n    </div>\n    <div style=\"border-top: 1px dashed #00C6FF; padding-top: 10px; margin-top: 12px; font-size: 14px; color: #CBD5E1;\">\n      <b>Issued in Public Interest by:</b> Department of Jal Shakti, Ministry of Jal Resources, New Delhi\n    </div>\n  </div>\n\n  <!-- SECTION 3: CLASSIFIED ADVERTISEMENTS -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 35px;\">3. Classified &amp; Display Advertisements Masterclass</h2>\n  <p>Advertisements are public notices designed to sell products, lease properties, hire manpower, or provide services. In Class 11 examinations, candidates are primarily tested on <b>Classified Advertisements</b> published in daily newspapers under designated categorical columns.</p>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(i) The Telegraphic Economy of Words:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Since newspapers charge advertisers per word or per column centimeter, classified ads use telegraphic syntax. Auxiliary verbs (is, are, was), articles (a, an, the), and connecting conjunctions are eliminated. Sentences are broken into comma-separated descriptive fragments without sacrificing clarity.</p>\n    </div>\n\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #00C6FF; font-size: 16px;\">(ii) Standard Classified Categories &amp; Key Ingredients:</b>\n      <div style=\"margin-top: 8px; color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n        &bull; <b style=\"color: #00C6FF;\">Situation Vacant:</b> Begins with <i>&ldquo;WANTED&rdquo;</i> or <i>&ldquo;REQUIRED&rdquo;</i>. Mentions post, number of vacancies, minimum educational qualification, years of experience, age limit, personality traits, remuneration/salary package, mode of applying, and deadline.<br/>\n        &bull; <b style=\"color: #00C6FF;\">Situation Wanted:</b> Begins with <i>&ldquo;AVAILABLE&rdquo;</i>. Written by a job seeker. Highlights personal qualifications, professional credentials, current post, desired role, expected emoluments, and contact number.<br/>\n        &bull; <b style=\"color: #00C6FF;\">For Sale (Property / Vehicle):</b> Begins with <i>&ldquo;FOR SALE&rdquo;</i> or <i>&ldquo;AVAILABLE FOR SALE&rdquo;</i>. For property: type (flat/kothi), size/area, number of rooms, facing, furnishing, location, amenities (water, electricity, parking), price expectation, contact. For vehicle: brand, model, year, mileage, color, single-owner, insurance, price negotiable.<br/>\n        &bull; <b style=\"color: #00C6FF;\">To Let / Accommodation Wanted:</b> Begins with <i>&ldquo;TO LET&rdquo;</i> or <i>&ldquo;WANTED ON RENT&rdquo;</i>. Type of property, location, fixtures, 24-hour power backup, preferred tenants (family/bachelors/corporate), expected monthly rent.<br/>\n        &bull; <b style=\"color: #00C6FF;\">Lost and Found:</b> Begins with <i>&ldquo;LOST&rdquo;</i> or <i>&ldquo;FOUND&rdquo;</i>. Precise description of object (color, brand, make), when and where lost/found, promised reward (for lost), contact address/mobile.\n      </div>\n    </div>\n  </div>\n\n  <!-- CLASSIFIED AD COMPARISON MATRIX -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 35px;\">4. Master Comparative Checklist: Notice vs. Poster vs. Classified Ad</h2>\n  <div style=\"overflow-x: auto; margin: 18px 0;\">\n    <table style=\"width: 100%; border-collapse: collapse; background: rgba(0,0,0,0.35); font-size: 14.5px;\">\n      <thead>\n        <tr style=\"background: rgba(0, 198, 255, 0.2); color: #00C6FF;\">\n          <th style=\"border: 1px solid rgba(0, 198, 255, 0.4); padding: 10px; text-align: left;\">Parameter</th>\n          <th style=\"border: 1px solid rgba(0, 198, 255, 0.4); padding: 10px; text-align: left;\">Notice</th>\n          <th style=\"border: 1px solid rgba(0, 198, 255, 0.4); padding: 10px; text-align: left;\">Poster</th>\n          <th style=\"border: 1px solid rgba(0, 198, 255, 0.4); padding: 10px; text-align: left;\">Classified Ad</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #80D8FF;\">Primary Goal</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Inform targeted group internally</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Persuade &amp; arouse public emotion</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Commercial deal, hiring, buying/selling</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #80D8FF;\">Visual Layout</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Strict formal block structure</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Creative slogans, symbols, columns</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Telegraphic, compact word blocks</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #80D8FF;\">Language Style</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Formal, 3rd person, passive voice</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Catchy, poetic, imperative slogans</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Telegraphic phrases; no complete sentences</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #80D8FF;\">Box Required?</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; color: #00E676;\">YES (Mandatory)</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; color: #00E676;\">YES (Mandatory)</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; color: #00E676;\">YES (Mandatory)</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #80D8FF;\">Word Limit</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">50 Words Maximum</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">50 Words Equivalent</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">50 Words Maximum</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- EXAM PITFALLS & TRAPS -->\n  <div style=\"background: rgba(255, 82, 82, 0.08); border-left: 4px solid #FF5252; padding: 16px; border-radius: 6px; margin: 24px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 17px; font-weight: bold;\">⚠️ Critical Board Exam Pitfalls to Avoid:</h3>\n    <ul style=\"margin: 0; padding-left: 20px; color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <li><b>Forgetting the Outer Box:</b> Always use a pencil and ruler to enclose the entire composition inside a clean rectangular boundary.</li>\n      <li><b>Writing Incomplete Contact Details:</b> An advertisement or notice without a contact person, telephone number, or email receives an immediate penalty on content.</li>\n      <li><b>Using 1st Person in Notices:</b> Never say <i>&ldquo;I want to inform you...&rdquo;</i> or <i>&ldquo;We are happy to announce...&rdquo;</i>. Use <i>&ldquo;Notice is hereby given...&rdquo;</i> or <i>&ldquo;This is to inform that...&rdquo;</i>.</li>\n      <li><b>Over-elaborating in Classified Ads:</b> Do not write lengthy essays. State requirements, features, and terms succinctly.</li>\n    </ul>\n  </div>\n\n</div>\n";

export const c11EngW2HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <div style=\"background: rgba(0, 198, 255, 0.06); border: 1.5px solid #00C6FF; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #00C6FF; margin: 0 0 6px 0; font-size: 20px; font-weight: bold;\">📚 High-Scoring Board Exemplars &amp; Model Solutions</h2>\n    <p class=\"text-center\" style=\"color: #80D8FF; margin: 0; font-size: 14.5px;\">15 High-Yield Solved Board Compositions (Notices, Posters &amp; Classified Advertisements)</p>\n  </div>\n\n  <!-- SECTION A: NOTICE WRITING SOLVED SAMPLES -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 25px;\">Part A: Notice Writing Solved Exemplars (100% Board Standard)</h2>\n\n  <!-- SAMPLE 1 -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 1: School Annual Cultural Fest Notice</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are Navin/Navita, Secretary of the Cultural Club of Delhi Public School, Srinagar. Your school is celebrating its Annual Golden Jubilee Cultural Fest &lsquo;UDAAN 2026&rsquo;. Draft a notice in not more than 50 words inviting students to register for various cultural performances.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 16px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: bold; font-size: 16px; color: #FFFFFF;\">DELHI PUBLIC SCHOOL, SRINAGAR</div>\n      <div style=\"text-align: center; font-weight: 800; font-size: 18px; color: #00C6FF; letter-spacing: 2px; margin: 6px 0;\">NOTICE</div>\n      <div style=\"display: flex; justify-content: space-between; font-size: 14px; color: #CBD5E1; margin-bottom: 10px;\">\n        <span><b>Date:</b> 12th April 2026</span>\n        <span style=\"color: #64748B;\">Ref: DPS/CUL/2026/04</span>\n      </div>\n      <div style=\"text-align: center; font-weight: bold; font-size: 15.5px; color: #FFD54F; margin-bottom: 12px; text-decoration: underline;\">\n        AUDITIONS FOR ANNUAL CULTURAL FEST &lsquo;UDAAN 2026&rsquo;\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        The Cultural Club is organizing the Annual Golden Jubilee Cultural Fest &lsquo;UDAAN 2026&rsquo; on 2nd May 2026 in the School Auditorium from 9:00 AM onwards. Auditions for solo/group singing, classical dance, mime, and theatrical drama will take place on 20th April 2026 in Room No. 204. Interested students of Classes IX to XII must register their names with the undersigned by 18th April 2026.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        <div>Sd/-</div>\n        <div style=\"font-weight: bold; color: #FFFFFF;\">NAVIN SHARMA</div>\n        <div style=\"color: #80D8FF;\">Secretary, Cultural Club</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- SAMPLE 2 -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 2: Lost &amp; Found Notice (Titan Wristwatch)</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are Aarav/Aanya of Class XI-A, Model Academy, Jammu. You lost your black metallic Titan wristwatch in the Senior Chemistry Laboratory during the 4th period. Draft a notice in not more than 50 words requesting the finder to return it.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 16px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: bold; font-size: 16px; color: #FFFFFF;\">MODEL ACADEMY, JAMMU</div>\n      <div style=\"text-align: center; font-weight: 800; font-size: 18px; color: #00C6FF; letter-spacing: 2px; margin: 6px 0;\">NOTICE</div>\n      <div style=\"display: flex; justify-content: space-between; font-size: 14px; color: #CBD5E1; margin-bottom: 10px;\">\n        <span><b>Date:</b> 18th August 2026</span>\n      </div>\n      <div style=\"text-align: center; font-weight: bold; font-size: 15.5px; color: #FFD54F; margin-bottom: 12px; text-decoration: underline;\">\n        LOST! TITAN WRISTWATCH IN CHEMISTRY LAB\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        A black metallic &lsquo;Titan Octane&rsquo; chronograph wristwatch with a circular dial and silver buckle was lost in the Senior Chemistry Laboratory during the 4th period on 17th August 2026. The watch bears emotional value. Anyone who finds it is kindly requested to hand it over to the undersigned or to the Chemistry Lab Assistant. A suitable treat is promised to the finder.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        <div>Sd/-</div>\n        <div style=\"font-weight: bold; color: #FFFFFF;\">AARAV GUPTA</div>\n        <div style=\"color: #80D8FF;\">Class XI-A (Roll No. 14)</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- SAMPLE 3 -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 3: Blood Donation Camp Notice</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are the President of the Residents&rsquo; Welfare Association (RWA), Green Park Enclave, Chandigarh. In association with the Red Cross Society, the RWA is organizing a Voluntary Blood Donation Camp. Draft a notice in 50 words appealing to residents to participate.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 16px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: bold; font-size: 16px; color: #FFFFFF;\">RESIDENTS&rsquo; WELFARE ASSOCIATION, GREEN PARK, CHANDIGARH</div>\n      <div style=\"text-align: center; font-weight: 800; font-size: 18px; color: #00C6FF; letter-spacing: 2px; margin: 6px 0;\">NOTICE</div>\n      <div style=\"display: flex; justify-content: space-between; font-size: 14px; color: #CBD5E1; margin-bottom: 10px;\">\n        <span><b>Date:</b> 5th September 2026</span>\n      </div>\n      <div style=\"text-align: center; font-weight: bold; font-size: 15.5px; color: #FFD54F; margin-bottom: 12px; text-decoration: underline;\">\n        VOLUNTARY BLOOD DONATION CAMP &mdash; DONATE BLOOD, SAVE LIVES\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        The RWA, in collaboration with the Indian Red Cross Society, is hosting a Voluntary Blood Donation Camp on Sunday, 14th September 2026, from 9:30 AM to 4:00 PM at the Community Centre. Healthy individuals between 18 and 60 years of age are warmly invited to donate. Refreshments, donor certificates, and blood donor identity cards will be provided to all donors.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        <div>Sd/-</div>\n        <div style=\"font-weight: bold; color: #FFFFFF;\">SURINDER MEHTA</div>\n        <div style=\"color: #80D8FF;\">President, RWA Green Park Enclave</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION B: POSTER DESIGNING SOLVED SAMPLES -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 35px;\">Part B: Poster Designing Solved Exemplars</h2>\n\n  <!-- SAMPLE 4: ANTI-DRUGS POSTER -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 4: Social Awareness Poster &mdash; &ldquo;Say NO to Drugs&rdquo;</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> Design an impactful, eye-catching poster in not more than 50 words for the Directorate of School Education, raising awareness among teenagers against drug abuse. Include captivating slogans and preventive messages.\n    </p>\n    <div style=\"background: #0B192C; border: 2px solid #00C6FF; border-radius: 8px; padding: 16px; text-align: center;\">\n      <div style=\"font-size: 22px; font-weight: 900; color: #FF5252; letter-spacing: 2px; margin-bottom: 6px;\">\n        ☠ DRUGS PROMISE PLEASURE &bull; BUT DELIVER DEATH! ☠\n      </div>\n      <div style=\"font-size: 17px; font-weight: bold; color: #FFEB3B; margin-bottom: 12px;\">\n        CHOOSE LIFE &bull; NOT DEATH &bull; SAY ABSOLUTE &lsquo;NO&rsquo; TO DRUGS!\n      </div>\n      <div style=\"display: flex; justify-content: space-around; background: rgba(0,0,0,0.35); padding: 12px; border-radius: 6px; margin: 12px 0; text-align: left;\">\n        <div style=\"width: 48%;\">\n          <b style=\"color: #FF8A65; font-size: 14.5px; display: block; margin-bottom: 6px;\">WHAT DRUGS DO TO YOU:</b>\n          <span style=\"font-size: 13.5px; color: #FFFFFF; line-height: 1.6;\">\n            &bull; Destroys nervous system &amp; organs<br/>\n            &bull; Ruins academic &amp; career prospects<br/>\n            &bull; Tears families apart emotionally<br/>\n            &bull; Leads to financial ruin &amp; crime\n          </span>\n        </div>\n        <div style=\"width: 48%;\">\n          <b style=\"color: #00E676; font-size: 14.5px; display: block; margin-bottom: 6px;\">WHAT YOU SHOULD DO:</b>\n          <span style=\"font-size: 13.5px; color: #FFFFFF; line-height: 1.6;\">\n            &bull; Seek help from parents &amp; teachers<br/>\n            &bull; Engage in sports, arts &amp; fitness<br/>\n            &bull; Resist negative peer pressure<br/>\n            &bull; Call Toll-Free Helpline: 1800-11-0031\n          </span>\n        </div>\n      </div>\n      <div style=\"font-size: 15px; color: #80D8FF; font-weight: bold; margin: 8px 0;\">\n        &ldquo;YOUR LIFE IS PRECIOUS &mdash; DO NOT SNUFF IT OUT FOR A MOMENTARY HIGH!&rdquo;\n      </div>\n      <div style=\"border-top: 1px dashed #00C6FF; padding-top: 8px; font-size: 13.5px; color: #CBD5E1;\">\n        <b>Issued in Public Interest by:</b> Directorate of School Education &amp; Youth Welfare Services\n      </div>\n    </div>\n  </div>\n\n  <!-- SAMPLE 5: ROAD SAFETY POSTER -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 5: Public Interest Poster &mdash; &ldquo;Road Safety Week&rdquo;</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> Design a poster for Delhi Traffic Police promoting Road Safety Rules during &lsquo;National Road Safety Week&rsquo;. Emphasize helmets, seatbelts, speed limits, and avoiding mobile phone distractions.\n    </p>\n    <div style=\"background: #0B192C; border: 2px solid #00C6FF; border-radius: 8px; padding: 16px; text-align: center;\">\n      <div style=\"font-size: 21px; font-weight: 900; color: #00E676; letter-spacing: 1.5px; margin-bottom: 6px;\">\n        🚦 SPEED THRILLS &bull; BUT IT KILLS! 🚦\n      </div>\n      <div style=\"font-size: 16px; font-weight: bold; color: #FFD54F; margin-bottom: 12px;\">\n        BETTER BE MISTER LATE &mdash; THAN LATE MISTER!\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px 14px; border-radius: 6px; margin: 10px 0; text-align: left;\">\n        <b style=\"color: #80D8FF; font-size: 14px; display: block; margin-bottom: 4px;\">FOUR GOLDEN LIFELINES ON ROAD:</b>\n        <span style=\"font-size: 13.5px; color: #FFFFFF; line-height: 1.6;\">\n          1. <b>Always wear a certified ISI Helmet</b> &mdash; riders and pillion riders alike.<br/>\n          2. <b>Fasten Seatbelts</b> &mdash; front and rear seats without exception.<br/>\n          3. <b>Never Drink and Drive</b> &mdash; call a cab or designate a sober driver.<br/>\n          4. <b>Don&rsquo;t Text While Driving</b> &mdash; that message can wait; your life cannot!\n        </span>\n      </div>\n      <div style=\"font-size: 14.5px; color: #FF5252; font-weight: bold; margin: 8px 0;\">\n        ALERT TODAY &mdash; ALIVE TOMORROW! DRIVE SAFELY &amp; ARRIVE HAPPY!\n      </div>\n      <div style=\"border-top: 1px dashed #00C6FF; padding-top: 8px; font-size: 13.5px; color: #CBD5E1;\">\n        <b>Issued in Public Interest by:</b> Traffic Police Headquarters, New Delhi &bull; Dial 1095 for Assistance\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION C: CLASSIFIED ADVERTISEMENTS SOLVED SAMPLES -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 35px;\">Part C: Classified Advertisements Solved Exemplars</h2>\n\n  <!-- SAMPLE 6: SITUATION VACANT -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 6: Situation Vacant &mdash; PGT Mathematics</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are the Principal of Silver Oak International School, Dehradun. You require a dynamic and qualified PGT Mathematics teacher for Senior Secondary classes. Draft a classified advertisement in not more than 50 words for the &lsquo;Situation Vacant&rsquo; column of a national daily.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 14px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: 800; font-size: 16px; color: #FFD54F; text-decoration: underline; margin-bottom: 8px;\">\n        SITUATION VACANT\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        WANTED a dynamic, highly competent PGT Mathematics for Classes XI&ndash;XII. Candidate must hold M.Sc. (Maths) with B.Ed. from a recognized university and possess a minimum of 5 years of teaching experience in reputed CBSE-affiliated schools. Excellent command over English and proficiency in digital smart boards essential. Age below 45 years. Salary commensurate with qualifications and 7th Pay Commission norms. Send comprehensive resume with recent photograph within 10 days to the Principal, Silver Oak International School, Rajpur Road, Dehradun, or email at <i>careers@silveroakddn.edu.in</i>. Ph: 0135-2748901.\n      </p>\n    </div>\n  </div>\n\n  <!-- SAMPLE 7: FOR SALE -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 7: For Sale &mdash; Independent 3-BHK Luxury Flat</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are moving abroad and wish to sell your 3-BHK fully furnished luxury apartment in a prime residential society of Gurugram. Draft a classified advertisement in not more than 50 words under the &lsquo;For Sale&rsquo; column.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 14px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: 800; font-size: 16px; color: #FFD54F; text-decoration: underline; margin-bottom: 8px;\">\n        FOR SALE\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        AVAILABLE for immediate sale, a prime 3-BHK luxury apartment (super area 1,850 sq. ft.) on the 6th floor, DLF Phase-IV, Gurugram. North-east park facing, fully furnished with imported Italian marble, modular kitchen, wooden wardrobes, and air-conditioning. Features 24-hour power backup, dedicated covered basement parking, and clubhouse access. Freehold title with clear documents. Price ₹1.85 Crores (negotiable for genuine buyers). Owner relocating overseas. Contact: Mr. Rajesh Khanna, Mobile: 98112-34567 or email: <i>rkhanna.dlf@gmail.com</i>.\n      </p>\n    </div>\n  </div>\n\n  <!-- SAMPLE 8: TO LET -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 8: To Let &mdash; Prime Commercial Showroom Space</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You have a newly built commercial showroom space measuring 1,200 sq. ft. on the ground floor of a busy market in Connaught Place, New Delhi. Draft a classified ad under the &lsquo;To Let&rsquo; column in 50 words.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 14px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: 800; font-size: 16px; color: #FFD54F; text-decoration: underline; margin-bottom: 8px;\">\n        TO LET\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        AVAILABLE on long-term lease, a newly constructed ground-floor commercial showroom (1,200 sq. ft.) in Inner Circle, Connaught Place, New Delhi. 40-foot wide glass frontage, 100% power backup, central air-conditioning ducting, and attached washrooms. Ideal for banks, retail jewelers, multinational corporate offices, or branded apparel outlets. Expected rent ₹2.5 Lakhs per month (negotiable). Inspection by appointment only. Contact: Estate Manager, M/s Oberoi Properties, Phone: 011-23345678, Mobile: 98765-43210.\n      </p>\n    </div>\n  </div>\n\n  <!-- SAMPLE 9: LOST AND FOUND (BRIEFCASE) -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 9: Lost &amp; Found &mdash; Briefcase with Certificates</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> While traveling in a Delhi Metro train from Rajiv Chowk to Noida City Centre, you left behind a brown leather briefcase containing original academic degrees and property papers. Draft an advertisement in 50 words under the &lsquo;Lost and Found&rsquo; column.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 14px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: 800; font-size: 16px; color: #FFD54F; text-decoration: underline; margin-bottom: 8px;\">\n        LOST &amp; FOUND\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        LOST a dark brown &lsquo;Samsonite&rsquo; genuine leather executive briefcase in the Blue Line Metro train (Rajiv Chowk to Noida City Centre) on 10th October 2026 around 5:30 PM. Contains original Class X, XII, B.Tech degree certificates in the name of &lsquo;Kunal Verma&rsquo; and vital land registry documents. Finder is requested to return the documents to Kunal Verma, Flat 302, Sagar Apartments, Sector 15, Noida. Handover to Metro Station Controller also welcome. A handsome cash reward of ₹10,000 promised. Mobile: 99100-22334.\n      </p>\n    </div>\n  </div>\n\n  <!-- SAMPLE 10: SITUATION WANTED -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #00C6FF; margin-bottom: 8px;\">Sample 10: Situation Wanted &mdash; Senior Accountant / Auditor</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are a qualified Chartered Accountant with 8 years of corporate experience, seeking a part-time or flexible assignment in a reputed firm. Draft an ad for &lsquo;Situation Wanted&rsquo; in 50 words.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #00C6FF; border-radius: 8px; padding: 14px; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\">\n      <div style=\"text-align: center; font-weight: 800; font-size: 16px; color: #FFD54F; text-decoration: underline; margin-bottom: 8px;\">\n        SITUATION WANTED\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        AVAILABLE an experienced, ICAI-certified Chartered Accountant with 8 years of rich experience in statutory audits, GST compliance, income tax filing, and computerized accounting on Tally Prime and SAP. Seeks flexible or part-time senior financial consulting assignments with reputed industrial firms or MNCs in Chandigarh or Mohali. Reasonable and negotiable remuneration terms. Contact: CA Vivek Chawla, Mobile: 98140-55667, Email: <i>vivek.ca.audit@gmail.com</i>.\n      </p>\n    </div>\n  </div>\n\n  <!-- PART D: STEP-BY-STEP BOARD EXAM PRACTICE QUESTIONS -->\n  <h2 style=\"color: #00C6FF; font-weight: bold; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin-top: 35px;\">Part D: Step-by-Step Board Exam Practice Questions</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 18px; margin: 18px 0;\">\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #00C6FF; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #00C6FF; font-size: 15.5px;\">Practice Q1 (Notice &mdash; Educational Tour):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">You are the Secretary of the History Society, St. Xavier&rsquo;s High School, Mumbai. Draft a notice in 50 words announcing an educational excursion to the historical monuments of Rajasthan (Jaipur, Jodhpur, and Udaipur) for Class XI students. Mention itinerary duration, tour fee, inclusions, and deadline for submitting parental consent letters.</p>\n      <span style=\"color: #80D8FF; font-size: 14px;\"><b>Examiner Key:</b> Must include dates of travel, costs (e.g. ₹6,500 all-inclusive), teacher escorts, and submission deadline for consent forms.</span>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #00C6FF; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #00C6FF; font-size: 15.5px;\">Practice Q2 (Poster &mdash; Eye Donation Awareness):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">Design an inspirational poster in 50 words for the National Eye Bank, encouraging citizens to pledge their eyes after death to light up the dark world of visually impaired individuals. Include a catchy slogan, myths debunked, and contact details of the nearest collection center.</p>\n      <span style=\"color: #80D8FF; font-size: 14px;\"><b>Examiner Key:</b> Slogan: <i>&ldquo;Let Your Eyes See The World Even When You Are No More!&rdquo;</i> &bull; Clear call-to-action with registration hotline.</span>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #00C6FF; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #00C6FF; font-size: 15.5px;\">Practice Q3 (Classified Ad &mdash; Missing Pet Dog):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">Your family pet, a 2-year-old male Golden Retriever answering to the name &lsquo;Leo&rsquo;, went missing from Central Park, Jaipur. Draft a classified advertisement in 50 words under &lsquo;Missing Pets&rsquo; giving physical identification marks, collar color, and reward.</p>\n      <span style=\"color: #80D8FF; font-size: 14px;\"><b>Examiner Key:</b> Exact descriptors: Golden fur, black leather collar with bell, vaccination status, contact number, and declared reward.</span>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #00C6FF; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #00C6FF; font-size: 15.5px;\">Practice Q4 (Classified Ad &mdash; Vehicle For Sale):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">You want to sell your Maruti Suzuki Swift Dzire (VXI petrol, 2022 model, metallic grey) in excellent running condition. Draft an ad for the &lsquo;For Sale&rsquo; column in 50 words stating mileage, single-hand driving, accessories, price, and contact.</p>\n      <span style=\"color: #80D8FF; font-size: 14px;\"><b>Examiner Key:</b> Mention: Single owner, 28,000 km run, comprehensive insurance, touchscreen infotainment, price ₹5.75 Lakhs negotiable.</span>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #00C6FF; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #00C6FF; font-size: 15.5px;\">Practice Q5 (Notice &mdash; Inter-School Debate):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">You are the Head Girl of St. Mary&rsquo;s Convent, Shimla. Your school is organizing an Inter-School English Debate Competition on the topic &ldquo;Artificial Intelligence: Boon or Bane for Education?&rdquo;. Draft a notice in 50 words inviting class representatives to submit entries.</p>\n      <span style=\"color: #80D8FF; font-size: 14px;\"><b>Examiner Key:</b> 5 Ws: Date, time, venue, team composition (1 for, 1 against motion), prizes, and last date for submission.</span>\n    </div>\n  </div>\n\n</div>\n";

